import{_ as a,o,c as t,a2 as c}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"コンテンツ検索","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/content-search.md","filePath":"ja-JP/user-guide/content-search.md","lastUpdated":1788190459000}'),r={name:"ja-JP/user-guide/content-search.md"};function d(s,e,n,l,i,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="コンテンツ検索" tabindex="-1">コンテンツ検索 <a class="header-anchor" href="#コンテンツ検索" aria-label="Permalink to &quot;コンテンツ検索&quot;">​</a></h1><p>コンテンツ検索プラグインは、ローカルドキュメントの本文を検索し、バックグラウンドでインデックスを作成します。Lertaro の通常のファイル名検索と並行して利用できます。</p><h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p><strong>設定 → プラグイン → コンテンツ検索 → 設定</strong>を開き、少なくとも 1 つの監視フォルダーを指定して保存します。既定のトリガーキーワードは <code>cs</code> です。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cs プロジェクト計画</span></span></code></pre></div><p>キーワードの後にはスペースが必要です。<code>cs</code> が使いにくい場合は、プラグイン設定で別のキーワードに変更できます。</p><h2 id="インデックス対象" tabindex="-1">インデックス対象 <a class="header-anchor" href="#インデックス対象" aria-label="Permalink to &quot;インデックス対象&quot;">​</a></h2><ul><li><strong>監視フォルダー</strong>：設定したローカルフォルダーを再帰的にスキャンします。<code>%USERPROFILE%</code> などの環境変数にも対応します。</li><li><strong>ファイル拡張子</strong>：既定では <code>txt</code>、<code>md</code>、<code>pdf</code>、<code>docx</code>、<code>docm</code>、<code>pptx</code>、<code>pptm</code>、<code>xlsx</code>、<code>xlsm</code>、<code>csv</code> が対象です。カンマ区切りの一覧は変更できます。</li><li><strong>PDF ファイル</strong>：抽出可能なページ本文に加え、保存された入力可能 PDF フォームのフィールド値も検索します。</li><li><strong>ファイルサイズ</strong>：ファイルごとの上限を超えるファイルはスキップされます。コンテンツインデックスには別のサイズ上限があり、<code>0</code> で無制限になります。</li><li><strong>除外パス</strong>：セミコロン区切りの正規表現で完全パスを除外できます。フォルダーが一致すると、その内容も除外されます。</li></ul><p>本文の抽出に成功したファイルだけが検索対象になります。対応するドキュメント抽出器のないバイナリファイルは、読めない文字列として登録せずスキップされます。</p><h2 id="検索方法" tabindex="-1">検索方法 <a class="header-anchor" href="#検索方法" aria-label="Permalink to &quot;検索方法&quot;">​</a></h2><p>クイック検索ウィンドウで <code>cs</code>、スペース、キーワードの順に入力します。結果には一致したファイルの本文スニペットとフォルダーが表示され、<code>Enter</code> で選択したファイルを開けます。結果がある場合、種類フィルターを選択していなければフル検索ウィンドウにも同じファイル結果が表示されます。</p><p>初回インデックス作成中は、<code>cs</code> のプレースホルダーにインデックス済みファイル数と残りの作業数が表示されます。新規ファイルや変更されたファイルはバックグラウンドで処理されるため、通常のファイル名検索はそのまま利用できます。</p><h2 id="クリアと再構築" tabindex="-1">クリアと再構築 <a class="header-anchor" href="#クリアと再構築" aria-label="Permalink to &quot;クリアと再構築&quot;">​</a></h2><p>コンテンツ検索の設定には、次の 2 つの操作があります。</p><ul><li><strong>インデックスをクリア</strong>：コンテンツインデックスだけを削除し、監視フォルダーを再スキャンしません。</li><li><strong>インデックスを再構築</strong>：コンテンツインデックスを削除し、すべての監視フォルダーを再スキャンします。</li></ul><p>どちらの操作もコンテンツ検索インデックスだけに影響し、Lertaro の通常のファイル名インデックスは削除しません。</p><h2 id="ヒント" tabindex="-1">ヒント <a class="header-anchor" href="#ヒント" aria-label="Permalink to &quot;ヒント&quot;">​</a></h2><ul><li>ファイルが結果に出ない場合は、フォルダー、拡張子、除外パターン、サイズ上限を確認してください。</li><li>監視フォルダーやインデックスルールを変更した後は、設定を保存してバックグラウンドスキャンの完了を待ってください。</li><li>ルール変更後に既存ファイルを再抽出したい場合は、<strong>インデックスを再構築</strong>を使用してください。</li></ul>',18)])])}const g=a(r,[["render",d]]);export{u as __pageData,g as default};
